#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    bool maxSubstringLength(string s, int k) {
        if (k == 0) return true;
        int n = s.size();
        vector<int> first(26, -1), last(26, -1);
        for (int i = 0; i < n; i++) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }

        vector<pair<int, int>> intervals;
        for (int i = 0; i < 26; i++) {
            if (first[i] == -1) continue;
            int start = first[i];
            int end = last[i];
            bool valid = true;
            for (int j = start; j <= end; j++) {
                int c = s[j] - 'a';
                if (first[c] < start) {
                    valid = false;
                    break;
                }
                end = max(end, last[c]);
            }
            if (valid && !(start == 0 && end == n - 1)) {
                intervals.push_back({start, end});
            }
        }

        sort(intervals.begin(), intervals.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
            return a.second < b.second;
        });

        int count = 0;
        int prevEnd = -1;
        for (const auto& iv : intervals) {
            if (iv.first > prevEnd) {
                count++;
                prevEnd = iv.second;
            }
        }
        return count >= k;
    }
};

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public boolean maxSubstringLength(String s, int k) {
        if (k == 0) return true;
        int n = s.length();
        int[] first = new int[26];
        int[] last = new int[26];
        Arrays.fill(first, -1);
        Arrays.fill(last, -1);
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }

        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            if (first[i] == -1) continue;
            int start = first[i];
            int end = last[i];
            boolean valid = true;
            for (int j = start; j <= end; j++) {
                int c = s.charAt(j) - 'a';
                if (first[c] < start) {
                    valid = false;
                    break;
                }
                end = Math.max(end, last[c]);
            }
            if (valid && !(start == 0 && end == n - 1)) {
                intervals.add(new int[]{start, end});
            }
        }

        intervals.sort((a, b) -> Integer.compare(a[1], b[1]));
        int count = 0;
        int prevEnd = -1;
        for (int[] iv : intervals) {
            if (iv[0] > prevEnd) {
                count++;
                prevEnd = iv[1];
            }
        }
        return count >= k;
    }
}

/**
 * @param {string} s
 * @param {number} k
 * @return {boolean}
