var maxSubstringLength = function(s, k) {
    if (k === 0) return true;
    const n = s.length;
    const first = new Array(26).fill(-1);
    const last = new Array(26).fill(-1);
    const aCode = 'a'.charCodeAt(0);

    for (let i = 0; i < n; i++) {
        const c = s.charCodeAt(i) - aCode;
        if (first[c] === -1) first[c] = i;
        last[c] = i;
    }

    const intervals = [];
    for (let i = 0; i < 26; i++) {
        if (first[i] === -1) continue;
        const start = first[i];
        let end = last[i];
        let valid = true;
        for (let j = start; j <= end; j++) {
            const c = s.charCodeAt(j) - aCode;
            if (first[c] < start) {
                valid = false;
                break;
            }
            end = Math.max(end, last[c]);
        }
        if (valid && !(start === 0 && end === n - 1)) {
            intervals.push([start, end]);
        }
    }

    intervals.sort((a, b) => a[1] - b[1]);
    let count = 0;
    let prevEnd = -1;
    for (const [start, end] of intervals) {
        if (start > prevEnd) {
            count++;
            prevEnd = end;
        }
    }
    return count >= k;
};
